from scipy.ndimage import rank_filter
import numpy as np

def apply_rank_filter(A: np.ndarray, rank: int, size: int = None, footprint: np.ndarray = None, output: np.ndarray = None, mode: str = 'reflect', cval: float = 0.0, origin: int = 0) -> np.ndarray:
    if size is None and footprint is None:
        raise ValueError("Either size or footprint must be defined")
    if size is not None and footprint is not None:
        raise ValueError("Only one of size and footprint may be defined")
    if size is not None:
        footprint = np.ones(size, dtype=np.bool)
    return rank_filter(A, rank, footprint=footprint, output=output, mode=mode, cval=cval, origin=origin)

