from scipy.linalg import det
import numpy as np

def compute_determinant(A: np.ndarray) -> np.ndarray:
    # Check if A is a square matrix
    if A.shape[0] != A.shape[1]:
        raise ValueError('expected square matrix')

    # Compute the determinant of A
    return det(A)

