import numpy as np
from scipy.stats import hmean

def count_unique_hmean(data: np.ndarray) -> int:
    # data shape: (n, m)
    # n: number of arrays
    # m: number of elements in each array
    unique_values = set()
    for row in data:
        unique_values.add(hmean(row))
    return len(unique_values)

