from scipy.ndimage import median_filter
import numpy as np 
def apply_median_filter(A: np.ndarray,size:int) -> np.ndarray:
    # Check if the input is a batched array
    if len(A.shape) > 3:
        raise ValueError("Input array must be batched in the first dimension")

    # Check if the size parameter is valid
    if size < 1:
        raise ValueError("Size parameter must be greater than 0")

    # Apply the median filter to each image in the batch
    for i in range(A.shape[0]):
        A[i] = median_filter(A[i], size)

    return A

