import scipy.signal.windows as windows
import numpy as np

def compute_lanczos_window(window_size: int = 1024, sym: bool = True) -> np.ndarray:
    if window_size <= 0:
        return np.array([])
    if sym:
        return windows.cosine(window_size)
    else:
        return windows.flattop(window_size)

